import sys

def main():
    a, b = map(int, sys.stdin.read().strip().split())
    if (a + b) % 2 == 1:
        print("NO")
    else:
        total_steps = a + b
        if a <= total_steps // 2 and b <= total_steps // 2:
            print("YES")
        else:
            print("NO")

if __name__ == "__main__":
    main()
